from typing import List

def generate_cypress_imports() -> List[str]:
    return [
        "// Cypress test generated by Automation Script Generator",
    ]

def generate_cypress_test_wrapper(step_calls: List[str], test_id: str, run_id: str) -> List[str]:
    lines = [
        "describe('Test Flow', () => {",
        f"  const testCaseId = '{test_id}';",
        f"  const runId = '{run_id}';",
        "  const artifactsDir = `artifacts/${testCaseId}/${runId}`;",
        "  const successDir = `${artifactsDir}/success`;",
        "  const failuresDir = `${artifactsDir}/failures`;",
        "  const summaryPath = `${failuresDir}/summary.json`;",
        "  let stepMetrics = [];",
        "  let failed = false;",
        "  let consoleLogs = [];",
        "",
        "  Cypress.on('window:before:load', (win) => {",
        "    ['log', 'info', 'error', 'warn'].forEach((method) => {",
        "      const original = win.console[method];",
        "      win.console[method] = function(...args) {",
        "        consoleLogs.push(`[${method.toUpperCase()}] ${args.join(' ')}`);",
        "        original.apply(win.console, args);",
        "      };",
        "    });",
        "  });",
        "",
        "  before(() => {",
        "    cy.writeFile(`${artifactsDir}/status.txt`, 'running');",
        "    cy.writeFile(`${artifactsDir}/exit_code.txt`, '1');",
        "    cy.writeFile(`${artifactsDir}/started_at.txt`, new Date().toISOString());",
        "  });",
        "",
        "  after(() => {",
        "    const status = failed ? 'failed' : 'passed';",
        "    const exitCode = failed ? '1' : '0';",
        "    cy.writeFile(`${artifactsDir}/status.txt`, status);",
        "    cy.writeFile(`${artifactsDir}/exit_code.txt`, exitCode);",
        "    cy.writeFile(`${artifactsDir}/finished_at.txt`, new Date().toISOString());",
        "",
        "    const finalSummaryPath = failed ? summaryPath : `${successDir}/summary.json`;",
        "    cy.writeFile(finalSummaryPath, JSON.stringify({",
        "      test_case_id: testCaseId,",
        "      run_id: runId,",
        "      status: status,",
        "      steps: stepMetrics",
        "    }, null, 2));",
        "  });",
        "",
        "  beforeEach(() => {",
        "    consoleLogs = []; // Reset logs per step",
        "  });",
        "",
        "  afterEach(function() {",
        "    const stepName = this.currentTest.title;",
        "    const duration = this.currentTest.duration || 0;",
        "    const state = this.currentTest.state;",
        "    const isPassed = state === 'passed';",
        "    const error = this.currentTest.err;",
        "    const stepCode = this.currentTest.body ? this.currentTest.body.toString() : '';",
        "",
        "    const metric = {",
        "      step_name: stepName,",
        "      status: isPassed ? 'passed' : 'failed',",
        "      duration_total_sec: duration / 1000,",
        "      attempts: 1,",
        "      step_code_hash: Cypress._.uniqueId('hash_')",
        "    };",
        "    stepMetrics.push(metric);",
        "",
        "    cy.url().then((url) => {",
        "      metric.url = url;",
        "      const stepSummary = { ...metric, started_at: new Date(Date.now() - duration).toISOString(), ended_at: new Date().toISOString() };",
        "",
        "      if (!isPassed) {",
        "        failed = true;",
        "        const failureDir = `${failuresDir}/${stepName}/attempt_1`;",
        "        cy.screenshot(`${failureDir}/screenshot`, { overwrite: true });",
        "        cy.writeFile(`${failureDir}/console.txt`, consoleLogs.join('\\n'));",
        "        cy.writeFile(`${failureDir}/step_code.js`, stepCode);",
        "        if (error) {",
        "          cy.writeFile(`${failureDir}/error.txt`, error.message || 'Unknown error');",
        "          cy.writeFile(`${failureDir}/traceback.txt`, error.stack || '');",
        "        }",
        "        cy.document().then((doc) => {",
        "          cy.writeFile(`${failureDir}/dom.html`, doc.documentElement.outerHTML);",
        "        });",
        "      } else {",
        "        const successStepDir = `${successDir}/${stepName}`;",
        "        cy.screenshot(`${successStepDir}/screenshot`, { overwrite: true });",
        "        cy.writeFile(`${successStepDir}/console.txt`, consoleLogs.join('\\n'));",
        "        cy.writeFile(`${successStepDir}/step_summary.json`, JSON.stringify(stepSummary, null, 2));",
        "      }",
        "    });",
        "  });",
        "",
    ]
    lines.extend(step_calls)
    lines.append("});")
    return lines
